function useToggle(initialValue) {
  const [value, setValue] = useState(initialValue)

  const toggle = useCallback(() => {
    setValue(v => !v)  // 외부 변수 참조 없음
  }, [])               // deps 빈 배열

  return [value, toggle]
}

